{"draft":{"version":"a0","html":"<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Aquarium de Papier</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #f4ecd8;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
  }
  canvas {
    touch-action: none;
    display: block;
  }
  #hud {
    position: absolute;
    top: 10px;
    left: 0;
    right: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 14px;
    box-sizing: border-box;
    pointer-events: none;
  }
  #counter {
    background: #3d405b;
    color: #f4ecd8;
    font-weight: 700;
    font-size: 18px;
    padding: 10px 16px;
    border-radius: 12px;
    box-shadow: 2px 3px 6px rgba(0,0,0,0.25);
  }
  #clearBtn {
    pointer-events: auto;
    background: #e07a5f;
    color: #f4ecd8;
    border: none;
    font-weight: 700;
    font-size: 16px;
    padding: 12px 18px;
    border-radius: 12px;
    box-shadow: 2px 3px 6px rgba(0,0,0,0.25);
    min-height: 44px;
    min-width: 44px;
    cursor: pointer;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
</style>
</head>
<body>
<div id="wrap">
  <div id="hud">
    <div id="counter">Poissons : 0</div>
    <button id="clearBtn">Vider le bocal</button>
  </div>
  <canvas id="game"></canvas>
</div>
<script>
const CARTRIDGE = {
  send(type, payload = {}) {
    window.parent.postMessage(
      { source: "cartridge", v: 1, type, payload },
      "*",
    );
  },
};
</script>
<script>
(function () {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const counterEl = document.getElementById("counter");
  const clearBtn = document.getElementById("clearBtn");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  // paper-cut palette
  const COLORS = {
    bg: "#f4ecd8",
    layer: "#e07a5f",
    accent: "#3d405b",
    highlight: "#81b29a"
  };

  const fishColors = ["#e07a5f", "#81b29a", "#3d405b", "#f2cc8f", "#c98474"];

  let paused = false;
  let running = false;
  let started = false;

  // seeded jitter helper so shapes don't flicker
  function seededRandom(seed) {
    let s = seed % 2147483647;
    if (s <= 0) s += 2147483646;
    return function () {
      s = (s * 16807) % 2147483647;
      return (s - 1) / 2147483646;
    };
  }

  const fish = []; // {x,y,baseY,angle,speed,phase,color,size,jitterSeed}
  let tally = 0;

  function jarBounds() {
    // jar occupies central area
    const margin = Math.min(W, H) * 0.08;
    const jarW = W - margin * 2;
    const jarH = H * 0.62;
    const jarX = margin;
    const jarY = H * 0.18;
    return { x: jarX, y: jarY, w: jarW, h: jarH };
  }

  function resize() {
    dpr = Math.max(1, window.devicePixelRatio || 1);
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  resize();

  function makeFish(x, y) {
    const rnd = seededRandom(Math.floor(x * 1000 + y * 7 + tally * 91 + 1));
    const size = 16 + rnd() * 10;
    const color = fishColors[Math.floor(rnd() * fishColors.length)];
    return {
      x, y,
      baseY: y,
      angle: rnd() * Math.PI * 2,
      dir: rnd() > 0.5 ? 1 : -1,
      speed: 0.4 + rnd() * 0.6,
      phase: rnd() * Math.PI * 2,
      wobble: 6 + rnd() * 6,
      color,
      size,
      seed: Math.floor(rnd() * 100000)
    };
  }

  function place(x, y) {
    const f = makeFish(x, y);
    fish.push(f);
    tally += 1;
    counterEl.textContent = "Poissons : " + tally;
    CARTRIDGE.send("score", { value: tally });
  }

  function clearTable() {
    fish.length = 0;
    tally = 0;
    counterEl.textContent = "Poissons : 0";
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  function backToTitle() {
    clearTable();
    started = false;
    running = false;
  }

  clearBtn.addEventListener("click", function (e) {
    e.stopPropagation();
    clearTable();
  });

  function jitterPoint(x, y, seed, amt) {
    const rnd = seededRandom(seed);
    return [x + (rnd() - 0.5) * amt * 2, y + (rnd() - 0.5) * amt * 2];
  }

  function drawRoundedJitterRect(x, y, w, h, r, seed, amt) {
    const pts = [
      [x + r, y],
      [x + w - r, y],
      [x + w, y + r],
      [x + w, y + h - r],
      [x + w - r, y + h],
      [x + r, y + h],
      [x, y + h - r],
      [x, y + r]
    ];
    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      const [jx, jy] = jitterPoint(pts[i][0], pts[i][1], seed + i, amt);
      if (i === 0) ctx.moveTo(jx, jy);
      else ctx.lineTo(jx, jy);
    }
    ctx.closePath();
  }

  function drawBackground() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, W, H);
  }

  function drawTitle() {
    ctx.save();
    ctx.fillStyle = COLORS.accent;
    ctx.font = "bold " + Math.round(Math.min(W, H) * 0.05) + "px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const pulse = 0.7 + 0.3 * Math.sin(Date.now() / 300);
    ctx.globalAlpha = pulse;
    ctx.fillText("Touchez pour commencer", W / 2, H * 0.12);
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawJar(bounds) {
    const { x, y, w, h } = bounds;
    // shadow layer behind jar
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;

    // jar body - paper layer
    ctx.fillStyle = "#ffffff";
    ctx.globalAlpha = 0.55;
    drawRoundedJitterRect(x, y, w, h, Math.min(w, h) * 0.08, 501, 1.5);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.restore();

    // jar rim (paper strip)
    ctx.save();
    ctx.fillStyle = COLORS.layer;
    ctx.shadowColor = "rgba(61,64,91,0.3)";
    ctx.shadowBlur = 5;
    ctx.shadowOffsetY = 2;
    const rimH = h * 0.06;
    drawRoundedJitterRect(x - w * 0.03, y - rimH * 0.4, w * 1.06, rimH, rimH * 0.4, 502, 1.5);
    ctx.fill();
    ctx.restore();

    // outline suggestion via slightly darker inner card edge (thin, not glow)
    ctx.save();
    ctx.strokeStyle = COLORS.accent;
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.5;
    drawRoundedJitterRect(x, y, w, h, Math.min(w, h) * 0.08, 501, 1.5);
    ctx.stroke();
    ctx.restore();
  }

  function drawWaterLine(bounds) {
    const { x, y, w, h } = bounds;
    const waterY = y + h * 0.12;
    ctx.save();
    ctx.fillStyle = COLORS.highlight;
    ctx.globalAlpha = 0.35;
    drawRoundedJitterRect(x + 2, waterY, w - 4, h * 0.85, Math.min(w, h) * 0.06, 777, 1.2);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawFishShape(f, t) {
    const wob = Math.sin(t * 0.002 * f.speed + f.phase) * f.wobble;
    const px = f.x + wob * f.dir * 0.2;
    const py = f.baseY + Math.sin(t * 0.0015 * f.speed + f.phase * 1.3) * 8;
    const size = f.size;
    const dir = f.dir;

    ctx.save();
    ctx.translate(px, py);
    ctx.scale(dir, 1);
    ctx.shadowColor = "rgba(61,64,91,0.3)";
    ctx.shadowBlur = 4;
    ctx.shadowOffsetY = 2;

    // body
    ctx.fillStyle = f.color;
    ctx.beginPath();
    const bodyPts = [
      [-size, 0],
      [-size * 0.3, -size * 0.55],
      [size * 0.7, -size * 0.3],
      [size, 0],
      [size * 0.7, size * 0.3],
      [-size * 0.3, size * 0.55]
    ];
    for (let i = 0; i < bodyPts.length; i++) {
      const [jx, jy] = jitterPoint(bodyPts[i][0], bodyPts[i][1], f.seed + i, 1.2);
      if (i === 0) ctx.moveTo(jx, jy);
      else ctx.lineTo(jx, jy);
    }
    ctx.closePath();
    ctx.fill();

    // tail
    ctx.beginPath();
    ctx.moveTo(-size, 0);
    ctx.lineTo(-size * 1.5, -size * 0.4);
    ctx.lineTo(-size * 1.5, size * 0.4);
    ctx.closePath();
    ctx.fill();

    // eye
    ctx.shadowBlur = 0;
    ctx.fillStyle = COLORS.accent;
    ctx.beginPath();
    ctx.arc(size * 0.55, -size * 0.05, size * 0.09, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  function draw() {
    const t = Date.now();
    drawBackground();
    const bounds = jarBounds();
    drawWaterLine(bounds);

    // clip fish to jar interior
    ctx.save();
    drawRoundedJitterRect(bounds.x + 3, bounds.y + 3, bounds.w - 6, bounds.h - 6, Math.min(bounds.w, bounds.h) * 0.07, 501, 1.5);
    ctx.clip();
    for (let i = 0; i < fish.length; i++) {
      drawFishShape(fish[i], t + i * 37);
    }
    ctx.restore();

    drawJar(bounds);

    if (!started) {
      drawTitle();
    }
  }

  function settle() {
    // fish positions animate purely by time in draw(); nothing to settle physically
  }

  function insideJar(x, y) {
    const b = jarBounds();
    return x > b.x && x < b.x + b.w && y > b.y && y < b.y + b.h;
  }

  function onTap(evt) {
    evt.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const x = evt.clientX - rect.left;
    const y = evt.clientY - rect.top;

    if (!started) {
      started = true;
      running = true;
      CARTRIDGE.send("start");
      // also place a fish on first tap if inside jar
      if (insideJar(x, y)) place(x, y);
      return;
    }
    if (insideJar(x, y)) {
      place(x, y);
    }
  }

  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", onTap);

  window.addEventListener("message", function (event) {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  function frame() {
    if (!paused) settle();
    draw();
    requestAnimationFrame(frame);
  }

  CARTRIDGE.send("boot", { title: "Aquarium de Papier", gameType: "toy-box", lang: "fr" });
  CARTRIDGE.send("start");
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

